import{_ as e,o as t,c as o,a3 as c}from"./chunks/framework.BZRC44LV.js";const u=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shortcuts.md","filePath":"guide/shortcuts.md"}'),r={name:"guide/shortcuts.md"};function a(n,d,h,l,s,i){return t(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p><code>Mod</code> is <code>Cmd</code> on macOS and <code>Ctrl</code> on Windows and Linux. All shortcuts except the line break, <code>Mod</code> + Click and <code>Ctrl</code> <code>Page Up</code> / <code>Page Down</code> can be changed.</p><h2 id="change-a-shortcut" tabindex="-1">Change a shortcut <a class="header-anchor" href="#change-a-shortcut" aria-label="Permalink to &quot;Change a shortcut&quot;">​</a></h2><p>Open <strong>Settings</strong> with <code>Mod</code> <code>,</code> and choose <strong>Keyboard shortcuts</strong>. Click the key of a command (or press <code>Enter</code> on it) and press the new keys: they work at once, in every tab. <code>Esc</code> cancels, and <code>Backspace</code> removes the shortcut.</p><ul><li>A shortcut needs <code>Ctrl</code> or <code>Alt</code> (on macOS <code>Cmd</code>, <code>Ctrl</code> or <code>Option</code>) with a key, or is an F key on its own.</li><li>If another command already has the keys, Blank says which one. Press them again to move them to the new command; the other one is then left without a shortcut.</li><li>A changed shortcut has a reset button next to it, and <strong>Reset all</strong> brings back every default.</li><li>Some keys stay with what they do everywhere, and Blank says why when you press them: <code>Mod</code> <code>A</code>, <code>C</code>, <code>V</code> and <code>X</code>, <code>Mod</code> <code>Backspace</code> and <code>Delete</code>, <code>Ctrl</code> <code>Page Up</code> / <code>Page Down</code>, <code>Alt</code> <code>F4</code> on Windows and Linux, and on macOS <code>Option</code> with a letter or digit (it types a character) and the text keys <code>Ctrl</code> <code>A</code>, <code>E</code>, <code>H</code> and <code>D</code>, <code>Option</code> <code>Backspace</code> and <code>Delete</code>, and <code>Ctrl</code> <code>Option</code> <code>Backspace</code>.</li></ul><p>The shortcuts are kept in <a href="./configuration#keyboard-shortcuts">blank.json</a>, which you can also edit by hand.</p><div class="info custom-block"><p class="custom-block-title">Keyboards with AltGr</p><p>On keyboard layouts that type characters with <code>AltGr</code> (Polish, German and many more), Windows and Linux report <code>AltGr</code> as <code>Ctrl</code> <code>Alt</code>. A shortcut with <code>Ctrl</code> <code>Alt</code> and a key that <code>AltGr</code> uses on your layout then runs the command instead of typing the character. Choose another key for that command in the settings.</p></div><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>New document</td><td><code>Mod</code> <code>N</code></td></tr><tr><td>Open file</td><td><code>Mod</code> <code>O</code></td></tr><tr><td>Save</td><td><code>Mod</code> <code>S</code></td></tr><tr><td>Save as</td><td><code>Mod</code> <code>Shift</code> <code>S</code></td></tr><tr><td>Export as PDF</td><td><code>Mod</code> <code>Alt</code> <code>P</code></td></tr><tr><td>Export as Word</td><td><code>Mod</code> <code>Alt</code> <code>W</code></td></tr><tr><td>Page setup</td><td><code>Mod</code> <code>Alt</code> <code>U</code></td></tr><tr><td>Edit header</td><td><code>Mod</code> <code>Alt</code> <code>H</code></td></tr><tr><td>Edit footer</td><td><code>Mod</code> <code>Alt</code> <code>F</code></td></tr><tr><td><a href="./pages#on-the-screen">Pages or page ends</a></td><td><code>Mod</code> <code>Alt</code> <code>V</code></td></tr><tr><td><a href="./pages#outline">Outline</a></td><td><code>Mod</code> <code>Alt</code> <code>O</code></td></tr><tr><td><a href="./writing#the-status-bar">Word count</a></td><td><code>Mod</code> <code>Alt</code> <code>C</code></td></tr><tr><td>Cycle themes</td><td><code>Mod</code> <code>Alt</code> <code>T</code></td></tr><tr><td>Choose language</td><td><code>Mod</code> <code>Alt</code> <code>L</code></td></tr><tr><td><a href="./writing#focus-mode">Focus mode</a></td><td><code>Mod</code> <code>Shift</code> <code>F</code></td></tr><tr><td><a href="./settings">Settings</a></td><td><code>Mod</code> <code>,</code></td></tr></tbody></table><h2 id="tabs-and-moving-around" tabindex="-1">Tabs and moving around <a class="header-anchor" href="#tabs-and-moving-around" aria-label="Permalink to &quot;Tabs and moving around&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td><a href="./writing#tabs">Next tab</a></td><td><code>Ctrl</code> <code>Tab</code>, or <code>Ctrl</code> <code>Page Down</code></td></tr><tr><td>Previous tab</td><td><code>Ctrl</code> <code>Shift</code> <code>Tab</code>, or <code>Ctrl</code> <code>Page Up</code></td></tr><tr><td>Close tab</td><td><code>Mod</code> <code>W</code></td></tr><tr><td>Reopen the file closed last</td><td><code>Mod</code> <code>Shift</code> <code>T</code></td></tr><tr><td>Move tab left</td><td><code>Ctrl</code> <code>Shift</code> <code>Page Up</code></td></tr><tr><td>Move tab right</td><td><code>Ctrl</code> <code>Shift</code> <code>Page Down</code></td></tr><tr><td>Go to the tabs, the toolbar, and back to the text</td><td><code>F6</code></td></tr><tr><td>The other way round</td><td><code>Shift</code> <code>F6</code></td></tr><tr><td>Go to the toolbar</td><td><code>Alt</code> <code>F10</code></td></tr></tbody></table><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>Undo</td><td><code>Mod</code> <code>Z</code></td></tr><tr><td>Redo</td><td><code>Mod</code> <code>Shift</code> <code>Z</code></td></tr><tr><td>Insert line break</td><td><code>Shift</code> <code>Enter</code></td></tr><tr><td>A screen up / down</td><td><code>Page Up</code> / <code>Page Down</code></td></tr><tr><td>Start / end of the line</td><td><code>Home</code> / <code>End</code></td></tr><tr><td>Start / end of the document</td><td><code>Ctrl</code> <code>Home</code> / <code>Ctrl</code> <code>End</code>, on macOS <code>Cmd</code> <code>↑</code> / <code>Cmd</code> <code>↓</code></td></tr></tbody></table><p>Add <code>Shift</code> to the last three to select as you go. When a block like a table of contents or an embed is selected, <code>↑</code> and <code>↓</code> move on to the text above or below it.</p><h2 id="blocks" tabindex="-1">Blocks <a class="header-anchor" href="#blocks" aria-label="Permalink to &quot;Blocks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>Paragraph</td><td><code>Mod</code> <code>0</code></td></tr><tr><td>Heading 1 – 6</td><td><code>Mod</code> <code>1</code> … <code>6</code></td></tr><tr><td>Bullet list, on or off</td><td><code>Mod</code> <code>8</code></td></tr><tr><td>Numbered list, on or off</td><td><code>Mod</code> <code>9</code></td></tr><tr><td>Code block</td><td>(none)</td></tr><tr><td>Indent list item</td><td><code>Tab</code></td></tr><tr><td>Outdent list item</td><td><code>Shift</code> <code>Tab</code></td></tr><tr><td>Indent code lines</td><td><code>Tab</code></td></tr><tr><td>Outdent code lines</td><td><code>Shift</code> <code>Tab</code></td></tr><tr><td>Blockquote, on or off</td><td><code>Mod</code> <code>G</code></td></tr><tr><td>Horizontal line</td><td><code>Mod</code> <code>H</code></td></tr><tr><td>Page break</td><td><code>Mod</code> <code>Enter</code></td></tr><tr><td>Table</td><td><code>Mod</code> <code>T</code></td></tr><tr><td><a href="./blocks#pane">Insert a block</a></td><td><code>Mod</code> <code>Alt</code> <code>B</code></td></tr></tbody></table><h2 id="forms" tabindex="-1">Forms <a class="header-anchor" href="#forms" aria-label="Permalink to &quot;Forms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>Next / previous field</td><td><code>Tab</code> / <code>Shift</code> <code>Tab</code></td></tr><tr><td>Next field, from a one-line one</td><td><code>Enter</code></td></tr><tr><td>New line, in a one-line field</td><td><code>Shift</code> <code>Enter</code></td></tr><tr><td>Select the whole form</td><td><code>Escape</code></td></tr></tbody></table><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>Insert a table</td><td><code>Mod</code> <code>T</code>, arrows, Enter</td></tr><tr><td>Next / previous cell</td><td><code>Tab</code> / <code>Shift</code> <code>Tab</code></td></tr><tr><td>Add a row (in the last cell)</td><td><code>Tab</code></td></tr><tr><td>New line in a cell</td><td><code>Enter</code></td></tr><tr><td>Select cells</td><td><code>Shift</code> + arrow keys</td></tr><tr><td>Select the cell, then the table</td><td><code>Mod</code> <code>A</code></td></tr><tr><td>Clear the selected cells</td><td><code>Backspace</code> or <code>Delete</code></td></tr><tr><td>Table mode, in a table</td><td><code>Mod</code> <code>T</code></td></tr></tbody></table><p>In table mode, the arrow keys insert rows and columns, <code>Shift</code> + arrows move them, and letters align (<code>L</code> <code>C</code> <code>R</code>), sort (<code>S</code>), merge (<code>M</code>) and switch headers (<code>H</code>). See <a href="./tables#change">Change a table</a> for all keys.</p><h2 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>Bold</td><td><code>Mod</code> <code>B</code></td></tr><tr><td>Italic</td><td><code>Mod</code> <code>I</code></td></tr><tr><td>Underline</td><td><code>Mod</code> <code>U</code></td></tr><tr><td>Code</td><td><code>Mod</code> <code>E</code></td></tr><tr><td>Insert or edit link</td><td><code>Mod</code> <code>K</code></td></tr><tr><td>Open link in browser</td><td><code>Mod</code> + Click</td></tr><tr><td>Insert or edit image</td><td><code>Mod</code> <code>Alt</code> <code>I</code></td></tr><tr><td>Align left</td><td><code>Mod</code> <code>Shift</code> <code>L</code></td></tr><tr><td>Center</td><td><code>Mod</code> <code>Shift</code> <code>E</code></td></tr><tr><td>Align right</td><td><code>Mod</code> <code>Shift</code> <code>R</code></td></tr><tr><td>Justify</td><td><code>Mod</code> <code>Shift</code> <code>J</code></td></tr></tbody></table><h2 id="spell-check" tabindex="-1">Spell check <a class="header-anchor" href="#spell-check" aria-label="Permalink to &quot;Spell check&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>Turn spell check on or off</td><td><code>Mod</code> <code>Alt</code> <code>S</code></td></tr><tr><td>Next misspelled word</td><td><code>Mod</code> <code>Alt</code> <code>N</code></td></tr><tr><td>Previous misspelled word</td><td><code>Mod</code> <code>Alt</code> <code>Shift</code> <code>N</code></td></tr><tr><td>Open the menu at the cursor</td><td><code>Shift</code> <code>F10</code> or the menu key</td></tr></tbody></table><p>See <a href="./spelling">Spell check</a> for what the menu offers.</p><p>You can also create most of these by typing markdown. See <a href="./writing#format-as-you-type">Format as you type</a>.</p>',27)])])}const m=e(r,[["render",a]]);export{u as __pageData,m as default};
